import { tv, type VariantProps } from "@/lib/beton/tv";

export const changelogEntry = tv({
  slots: {
    root: "flex flex-col gap-4 border-b-3 border-border py-8 first:pt-0 last:border-b-0 lg:flex-row lg:gap-10",
    aside: "flex shrink-0 flex-row items-center gap-3 lg:w-44 lg:flex-col lg:items-start",
    version:
      "w-fit border-3 border-border bg-secondary px-2 py-0.5 font-mono text-sm font-bold tabular-nums",
    date: "font-mono text-xs font-bold tracking-widest uppercase",
    body: "flex min-w-0 flex-1 flex-col gap-4",
    title: "font-display text-h3 font-black tracking-tight text-foreground",
    changes: "flex flex-col gap-2",
    change: "flex items-start gap-3",
    kind: "mt-0.5 w-20 shrink-0 border-2 border-border px-1.5 py-0.5 text-center font-mono text-xs font-bold tracking-widest uppercase",
  },
  variants: {
    kind: {
      added: { kind: "bg-success" },
      changed: { kind: "bg-secondary" },
      fixed: { kind: "bg-primary" },
      removed: { kind: "bg-danger" },
    },
  },
  defaultVariants: {
    kind: "added",
  },
});

export type ChangelogEntryVariants = VariantProps<typeof changelogEntry>;

import { changelogEntry, type ChangelogEntryVariants } from "@/lib/beton/recipes/changelog-entry.recipe";
import { useId, type ComponentProps, type ReactNode } from "react";

export type ChangeKind = NonNullable<ChangelogEntryVariants["kind"]>;

export interface Change {
  /** Added, changed, fixed or removed. */
  kind: ChangeKind;
  /** What happened, in one line. */
  summary: ReactNode;
}

export interface ChangelogEntryProps extends Omit<ComponentProps<"article">, "title"> {
  /** The version this entry covers. */
  version: ReactNode;
  /** When it went out. */
  date?: ReactNode;
  /** A machine-readable date, so the entry means something to a machine. */
  dateTime?: string;
  /** A headline for the release. */
  title?: ReactNode;
  /** What changed, grouped by kind. */
  changes?: Change[];
  /** The heading level. Defaults to h3, under a page heading and a year. */
  headingLevel?: 2 | 3 | 4;
}

/** One release: its version, its date and what changed. */
export function ChangelogEntry({
  version,
  date,
  dateTime,
  title,
  changes = [],
  headingLevel = 3,
  className,
  children,
  ...props
}: ChangelogEntryProps) {
  const styles = changelogEntry();
  const id = useId();
  const Heading = `h${headingLevel}` as const;

  return (
    <article
      {...props}
      aria-labelledby={`${id}-title`}
      className={styles.root({ class: className })}
    >
      <div className={styles.aside()}>
        <p className={styles.version()}>{version}</p>
        {date ? (
          <time dateTime={dateTime} className={styles.date()}>
            {date}
          </time>
        ) : null}
      </div>
      <div className={styles.body()}>
        <Heading id={`${id}-title`} className={styles.title()}>
          {title ?? version}
        </Heading>
        {changes.length ? (
          <ul className={styles.changes()}>
            {changes.map((change, index) => (
              <li key={index} className={styles.change()}>
                <span className={changelogEntry({ kind: change.kind }).kind()}>{change.kind}</span>
                <span>{change.summary}</span>
              </li>
            ))}
          </ul>
        ) : null}
        {children}
      </div>
    </article>
  );
}
